/**
 * Worker entry for a static site with `media.legacyUploads: true`.
 *
 * Assets are served first by Cloudflare; this Worker only sees requests that match no
 * deployed file (`assets.not_found_handling: "none"`, generated by
 * scripts/lib/aw-migration.mjs). Sites that also run the contact API write their own
 * `src/worker.ts` instead, which calls `legacyRedirect()` before Astro's handler; the
 * generated config prefers it when it exists (build.md §5b).
 */
import { handleAssetMiss, type AssetsBinding } from './lib/legacy-uploads';

interface Env {
  ASSETS: AssetsBinding;
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    return handleAssetMiss(request, env.ASSETS);
  },
};
